INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('abhinavagupta-sc:source:18.29','Abhinavagupta','gita.18.29','sa','commentary','।।18.29।।बुद्धेरिति। बुद्धिः निश्चयः। धृतिः सन्तोषः। सर्वो हि सुकृतं दुष्कृतं वा कृत्वा अन्ते अवश्यं कृतं करणीयं? किमन्येन ( S N किमनेन ) इति धियं गृह्णाति। अन्यथा क्रियाभ्यो व्युपरमे को हेतुः स्यात् अतः सर्वस्यैव धृतिरस्तीति तात्पर्यार्थः। पदार्थस्त्वप्रसिद्धो व्याख्याय ( स्य ) त एव।'),
('abhinavagupta-sc:source:18.30','Abhinavagupta','gita.18.30','sa','commentary','।।18.30 -- 18.32।।प्रवृत्तिमित्त्यादि तामसी मतेत्यन्तम्। अयथावत् -- असम्यक्।'),
('abhinavagupta-sc:source:18.31','Abhinavagupta','gita.18.31','sa','commentary','।।18.30 -- 18.32।।प्रवृत्तिमित्त्यादि तामसी मतेत्यन्तम्। अयथावत् -- असम्यक्।'),
('abhinavagupta-sc:source:18.32','Abhinavagupta','gita.18.32','sa','commentary','।।18.30 -- 18.32।।प्रवृत्तिमित्त्यादि तामसी मतेत्यन्तम्। अयथावत् -- असम्यक्।'),
('abhinavagupta-sc:source:18.33','Abhinavagupta','gita.18.33','sa','commentary','।।18.33 -- 18.35।।धृत्येत्यादि तामसी मतेत्यन्तम्। मनःप्राणेन्द्रियक्रियाः योगेन धारयति यथा किं ममोपभोगादिभिः सर्वथैवात्मारामो भूयासम्इति मन्वानः। प्रसङ्गेनेति -- न तथा अभिनिवेशेन। निद्राकलहादिष्वेव यया सन्तोषं बध्नाति तत्परतया? सा तामसी धृतिः।'),
('abhinavagupta-sc:source:18.34','Abhinavagupta','gita.18.34','sa','commentary','।।18.33 -- 18.35।।धृत्येत्यादि तामसी मतेत्यन्तम्। मनःप्राणेन्द्रियक्रियाः योगेन धारयति यथा किं ममोपभोगादिभिः सर्वथैवात्मारामो भूयासम्इति मन्वानः। प्रसङ्गेनेति -- न तथा अभिनिवेशेन। निद्राकलहादिष्वेव यया सन्तोषं बध्नाति तत्परतया? सा तामसी धृतिः।'),
('abhinavagupta-sc:source:18.35','Abhinavagupta','gita.18.35','sa','commentary','।।18.33 -- 18.35।।धृत्येत्यादि तामसी मतेत्यन्तम्। मनःप्राणेन्द्रियक्रियाः योगेन धारयति यथा किं ममोपभोगादिभिः सर्वथैवात्मारामो भूयासम्इति मन्वानः। प्रसङ्गेनेति -- न तथा अभिनिवेशेन। निद्राकलहादिष्वेव यया सन्तोषं बध्नाति तत्परतया? सा तामसी धृतिः।'),
('abhinavagupta-sc:source:18.36','Abhinavagupta','gita.18.36','sa','commentary','।।18.36 -- 18.39।।सुखमित्यादि तामसमुदाहृतमित्यन्तम्। तदात्वे? अभ्यासकाले। विषमिव? जन्मशताभ्यस्तविषयसङ्गस्य दुष्परिहारत्वात्। उक्तं च श्रुतौ -- क्षुरस्य धारा विषमा दुरत्यया इत्यादि।आत्मप्रसादात् बुद्धिप्रसादो जायते? अन्यस्यापेक्ष्यमाणस्याभावात्। विषयेन्द्रियाणां परस्परसंयोगज़ं,( S? -- संप्रयोगजम् ) सुखम्? चक्षुष इव रूपसंबन्धात्। निद्रातः आलस्येन प्रमादेन ( S? ? N आलस्येन शठतया प्रमादेन ) पूर्वं व्याख्यातेन यत् सुखं तत्तामसम्।'),
('abhinavagupta-sc:source:18.37','Abhinavagupta','gita.18.37','sa','commentary','।।18.36 -- 18.39।।सुखमित्यादि तामसमुदाहृतमित्यन्तम्। तदात्वे? अभ्यासकाले। विषमिव? जन्मशताभ्यस्तविषयसङ्गस्य दुष्परिहारत्वात्। उक्तं च श्रुतौ -- क्षुरस्य धारा विषमा दुरत्यया इत्यादि।आत्मप्रसादात् बुद्धिप्रसादो जायते? अन्यस्यापेक्ष्यमाणस्याभावात्। विषयेन्द्रियाणां परस्परसंयोगज़ं,( S? -- संप्रयोगजम् ) सुखम्? चक्षुष इव रूपसंबन्धात्। निद्रातः आलस्येन प्रमादेन ( S? ? N आलस्येन शठतया प्रमादेन ) पूर्वं व्याख्यातेन यत् सुखं तत्तामसम्।'),
('abhinavagupta-sc:source:18.38','Abhinavagupta','gita.18.38','sa','commentary','।।18.36 -- 18.39।।सुखमित्यादि तामसमुदाहृतमित्यन्तम्। तदात्वे? अभ्यासकाले। विषमिव? जन्मशताभ्यस्तविषयसङ्गस्य दुष्परिहारत्वात्। उक्तं च श्रुतौ -- क्षुरस्य धारा विषमा दुरत्यया इत्यादि।आत्मप्रसादात् बुद्धिप्रसादो जायते? अन्यस्यापेक्ष्यमाणस्याभावात्। विषयेन्द्रियाणां परस्परसंयोगज़ं,( S? -- संप्रयोगजम् ) सुखम्? चक्षुष इव रूपसंबन्धात्। निद्रातः आलस्येन प्रमादेन ( S? ? N आलस्येन शठतया प्रमादेन ) पूर्वं व्याख्यातेन यत् सुखं तत्तामसम्।'),
('abhinavagupta-sc:source:18.39','Abhinavagupta','gita.18.39','sa','commentary','।।18.36 -- 18.39।।सुखमित्यादि तामसमुदाहृतमित्यन्तम्। तदात्वे? अभ्यासकाले। विषमिव? जन्मशताभ्यस्तविषयसङ्गस्य दुष्परिहारत्वात्। उक्तं च श्रुतौ -- क्षुरस्य धारा विषमा दुरत्यया इत्यादि।आत्मप्रसादात् बुद्धिप्रसादो जायते? अन्यस्यापेक्ष्यमाणस्याभावात्। विषयेन्द्रियाणां परस्परसंयोगज़ं,( S? -- संप्रयोगजम् ) सुखम्? चक्षुष इव रूपसंबन्धात्। निद्रातः आलस्येन प्रमादेन ( S? ? N आलस्येन शठतया प्रमादेन ) पूर्वं व्याख्यातेन यत् सुखं तत्तामसम्।'),
('abhinavagupta-sc:source:18.40','Abhinavagupta','gita.18.40','sa','commentary','।।18.40।।न तदस्तीति। एवं कर्तृकर्मकरणानां ( N -- कारणानाम् ) बुद्धिधृत्योः सुखस्य च सत्त्वादिभेदभिन्नानां परस्पराङ्गाङ्गिभावबाध्यबाधकत्वसमुच्चयात् वृत्तिक्रमयौगपद्यादियोगात् ( S -- पद्यादिभेदात् ) अपरिसंख्येयभेदत्त्वात् विविधफलप्रसवसमर्थत्वम् इति। अनेन कर्मणां प्राक् सूत्रितं गहनत्वं वितत्य सहेतुकं निर्णीतम्। सर्वे चैते देवादिस्थावरान्ताः गुणत्रयसंबन्धं नातिक्रामन्ति। उक्तं हि -- आ ब्रह्मणश्च कीटान्तं ( S?N कीटाच्च ) न कश्चित्तत्त्वतः सुखी।करोति विकृतीस्तास्ताः सर्व एव जिजीविषुः ( S??N omit this second half of the verse ) ।।इतितत्त्वतो हि सुखं गुणातिक्रान्तमनसः? नेतरस्येत्याशयः।'),
('abhinavagupta-sc:source:18.41','Abhinavagupta','gita.18.41','sa','commentary','।।18.41 -- 18.60।।एवमियता षण्णां प्रत्येकं त्रिस्वरूपत्वं धृत्यादीनां च प्रतिपादितम्। तन्मध्यात् सात्त्विके राशौ वर्तमानो दैवीं संपदं प्राप्त इह ज्ञाने योग्यः? त्वं च तथाविधः इत्यर्जुनः प्रोत्साहितः।अधुना तु इदमुच्यते -- यदि तावदनया ज्ञानबुद्ध्या कर्मणि भवान् प्रवर्तते तदा स्वधर्मप्रवृत्त्या विज्ञानपूततया च न कर्मसंबन्धस्तव। अथैतन्नानुमन्यसे? तदवश्यं तव प्रवृत्त्या तावत् भाव्यम् जातेरेव तथाभावे स्थितत्वात्। यतः सर्वः स्वभावनियतः ( S??N स्वस्वभावनियतः ) कुतश्चिद्दोषात् तिरोहिततत्स्वभावः ( S??N -- हिततत्तत्स्वभावः ) कंचित्कालं भूत्वापि? तत्तिरोधायकविगमे स्वभावं व्यक्त्यापन्नं लभत एव। तथाहि एवंविधो वर्णनां स्वभावः। एवमवश्यंभाविन्यां प्रवृत्तौ ततः फलविभागिता भवेत्।।तदाह -- ब्राह्मणेत्यादि अवशोऽपि तत् इत्यन्तम्। ब्राह्मणादीनां कर्मप्रविभागनिरूपणस्य स्वभावोऽश्यं नातिक्रामति,( S? ? N omit न and read अतिक्रामति ) इति क्षत्रियस्वभावस्य भवतोऽनिच्छतोऽपि प्रकृतिः स्वभावाख्या नियोक्तृताम् अव्यभिचारेण भजते। केवलं तया नियुक्तस्य पुण्यपापसंबन्धः। अतः मदभिहितविज्ञानप्रमाणपुरःसरीकारेण कर्माण्यनुतिष्ठ। तथा सति बन्धो निवर्त्स्यति। इत्यस्यार्थस्य परिकरघटनतात्पर्यं ( S? ? N -- करबन्धघटन -- ) महावाक्यार्थस्य। अवान्तरवाक्यानां स्पष्टा ( ष्टोऽ ) र्थः।समासेन ( S omits समासेन ) ( श्लो. 50 ) संक्षेपेण। ज्ञानस्य? प्रागुक्तस्य। निष्ठां ( ष्ठा ) वाग्जालपरिहारेण निश्चितामाह। बुद्ध्या विशुद्धया इत्यादि सर्वमेतत् व्याख्यातप्रायमिति न पुनरायस्यते,( N -- रारभ्यते )।'),
